{
 "quarter": "Q4 FY26",
 "callDate": "2026-05-29",
 "guidance": [
  {
   "metric": "volume",
   "statement": "Achieve high single-digit volume growth in the band of about 8% to 10% going forward.",
   "quote": "we are still confident that demand conditions should continue giving us closer to high single-digit volume growth in the band of about 8 -10%, as we predict going forward.",
   "page": 20,
   "horizon": "next quarters / FY27",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Maintain margin guidance within the band of 18% to 20% going forward.",
   "quote": "we are trying to see that we get into that area of 8-10% volume growth. Excellent, Amit. Thank you so much. Excellent set of results. Congratulations once again. ... We are maintaining our margin guidance, which is there.",
   "page": 22,
   "horizon": "FY27 / upcoming quarters",
   "quantitative": true
  },
  {
   "metric": "capex",
   "statement": "Expect to commission the first phase of the VAM-VAE backward integration project in the first half of this year.",
   "quote": "We expect to commission first phase in the first half of this year.",
   "page": 11,
   "horizon": "H1 FY27",
   "quantitative": true
  },
  {
   "metric": "growth",
   "statement": "Industrial coatings will continue to grow much higher than decorative given infrastructure investments and government spending.",
   "quote": "Industrial coatings will continue to grow much higher than decorative, given the investment happening in the infrastructure and Government spending that is happening in this area.",
   "page": 18,
   "horizon": "Q1 / FY27",
   "quantitative": false
  },
  {
   "metric": "growth",
   "statement": "International business is expected to continue to grow and contribute strongly to growth.",
   "quote": "International business again is expected to continue to grow and therefore, both industrial and international will strongly contribute to our growth going forward, as far as Q1 is concerned.",
   "page": 18,
   "horizon": "Q1",
   "quantitative": false
  }
 ],
 "delivered": [
  {
   "metric": "volume",
   "statement": "Decorative business achieved 12.4% volume growth and 10.2% value growth in Q4.",
   "page": 11
  },
  {
   "metric": "volume",
   "statement": "Full coatings volume growth reached 12.7% and value growth reached 11% in Q4.",
   "page": 11
  },
  {
   "metric": "volume",
   "statement": "Full year volume growth was close to 9% with 4.3% value growth at the standalone level.",
   "page": 16
  },
  {
   "metric": "margin",
   "statement": "Gross margins reached an all-time high of about 45.6% for Q4.",
   "page": 15
  },
  {
   "metric": "revenue",
   "statement": "New products contributed a substantial 17% of revenues during the year.",
   "page": 11
  },
  {
   "metric": "dividend",
   "statement": "Declared a final dividend of Rs. 23 per share, totaling Rs. 27.5 per share for the year with a 60% payout ratio.",
   "page": 17
  }
 ],
 "tone": "confident on demand and volume momentum, cautious on geopolitical volatility, inflation, and pricing margins.",
 "pushback": [
  {
   "topic": "Price Hikes vs Margins",
   "gist": "Analysts questioned whether price hikes fully cover cost inflation and currency depreciation, and how margins will be protected.",
   "page": 19
  },
  {
   "topic": "Competitive Intensity",
   "gist": "Analysts probed if discounting and competitive intensity remain high despite inflationary pressures and recent price hikes.",
   "page": 21
  },
  {
   "topic": "Volume Sustainability",
   "gist": "Questions were raised on whether Q4/Q1 volumes were driven by dealer upstocking ahead of price hikes rather than true demand.",
   "page": 20
  },
  {
   "topic": "Historical Margin Comparison",
   "gist": "Pressed on why margins won't contract sharply like they did in the FY22 crude inflation cycle.",
   "page": 22
  }
 ]
